def effective_limit(value, default=10):
    if value is None:
        return default
    if value == 0:
        return 0
    if isinstance(value, int):
        if value < 0:
            raise ValueError('negative int not allowed')
        # positive int overrides default
        return value
    # if value is not int (maybe other), fallback? spec says positive int overrides default; zero disabled stays zero.
    # default behavior for other types? likely keep default? but preserve signature; assume int or None.
    # fallback to default for non-int non-None? but spec limited.
    # We'll raise or default? Safer return default.
